import {evaluateCMake} from './pico-cmake-control.js';
// Declarative CMake target importer, deliberately not a shell/CMake interpreter.
const sdk=new Set('pico_stdlib pico_multicore pico_sync pico_time pico_util pico_stdio_usb hardware_gpio hardware_irq hardware_adc hardware_pwm hardware_timer hardware_dma hardware_pio hardware_i2c hardware_spi hardware_uart hardware_sync pico_cyw43_arch_none tinyusb_device tinyusb_board'.split(' '));
function path(base,name){if(/^(?:[A-Za-z]:|\/|\\)|\\|\$|[<>]/.test(name))throw Error('CMake: proje dışı veya çözümlenmemiş yol: '+name);const parts=[];for(const p of (base?base+'/':'').concat(name).split('/')){if(!p||p==='.')continue;if(p==='..'){if(!parts.length)throw Error('CMake: proje dışına çıkılamaz.');parts.pop();}else parts.push(p);}return parts.join('/')||'.';}
function commands(text,file){let at=0,line=1,out=[];const fail=m=>{throw Error(file+':'+line+': '+m);};while(at<text.length){if(/\s/.test(text[at])){if(text[at++]==='\n')line++;continue;}if(text[at]==='#'){if(text.slice(at,at+3)==='#[[')fail('bracket comments are not supported');while(at<text.length&&text[at]!='\n')at++;continue;}const m=/^[A-Za-z_][A-Za-z_0-9]*/.exec(text.slice(at));if(!m)fail('CMake komutu bekleniyor.');const name=m[0].toLowerCase(),start=line;at+=m[0].length;while(/\s/.test(text[at]||'')&&at<text.length)at++;if(text[at++]!=='(')fail('Komut parantezi gerekli.');const args=[];let token='',quoted=false,inQuote=false;for(;;){if(at>=text.length)fail('Kapanmayan komut.');const ch=text[at++];if(ch==='\n')line++;if(ch==='"'){inQuote=!inQuote;quoted=true;continue;}if(ch==='\\'){if(!inQuote)fail('Kaçışlı yollar desteklenmiyor.');const c=text[at++];if(c!=='"'&&c!=='\\')fail('Kaçış biçimi desteklenmiyor.');token+=c;continue;}if(!inQuote&&(ch===')'||/\s/.test(ch)||ch==='#')){if(token||quoted)args.push({text:token,quoted});token='';quoted=false;if(ch===')')break;if(ch==='#')while(at<text.length&&text[at]!='\n')at++;continue;}if(!inQuote&&(ch==='('||ch==='['))fail('İç içe ifade/bracket argüman desteklenmiyor.');token+=ch;}out.push({name,args,line:start,file});}return out;}
function declarativePlan(files){
 const all=new Map(files.map(f=>[f.name,f.content]));if(!all.has('CMakeLists.txt'))return null;
 const targets=new Map(),vars=new Map([['CMAKE_SOURCE_DIR','.'],['PROJECT_SOURCE_DIR','.']]),visited=new Set();let executables=[];
 const expand=(arg,dir)=>{let t=arg.text.replace(/\$\{([A-Za-z_][\w]*)\}/g,(_,key)=>{if(key==='CMAKE_CURRENT_SOURCE_DIR'||key==='CMAKE_CURRENT_LIST_DIR')return dir||'.';if(!vars.has(key))throw Error('CMake: tanımsız değişken '+key);return vars.get(key).join?.(';')??vars.get(key);});if(/\$|\$ENV|\$</.test(t))throw Error('CMake: ortam/generator ifadesi desteklenmiyor.');return arg.quoted?[t]:t.split(';').filter(Boolean);};
 function read(file){if(visited.has(file))throw Error('CMake: yinelenen/döngüsel include '+file);visited.add(file);if(!all.has(file))throw Error('CMake dosyası bulunamadı: '+file);const dir=file.includes('/')?file.slice(0,file.lastIndexOf('/')):'';for(const cmd of commands(all.get(file),file)){try{const a=cmd.args.flatMap(x=>expand(x,dir)),[target,...rest]=a;const t=()=>{if(!targets.has(target))throw Error('Tanımsız hedef '+target);return targets.get(target);};switch(cmd.name){
 case 'cmake_minimum_required':if(a[0]!=='VERSION')throw Error('VERSION gerekli');break;
 case 'project':if(!target)throw Error('Proje adı gerekli');vars.set('PROJECT_NAME',[target]);break;
 case 'set':if(!target||a.some(x=>['CACHE','PARENT_SCOPE','FORCE'].includes(x)))throw Error('Yalnız yerel set(NAME values...) desteklenir.');vars.set(target,rest);break;
 case 'include':if(a.length!==1)throw Error('include tek dosya alır');if(target==='pico_sdk_import.cmake')break;read(path(dir,target));break;
 case 'add_subdirectory':if(a.length!==1)throw Error('add_subdirectory tek proje klasörü alır');read(path(dir,target)+'/CMakeLists.txt');break;
 case 'pico_sdk_init':if(a.length)throw Error('pico_sdk_init argüman almaz');break;
 case 'add_executable':case 'add_library':{if(!target||targets.has(target)||!/^\w[\w-]*$/.test(target))throw Error('Geçersiz/yinelenen hedef');let src=rest,kind=cmd.name==='add_executable'?'exe':'static';if(cmd.name==='add_library'&&['STATIC','INTERFACE'].includes(src[0])){kind=src[0].toLowerCase();src=src.slice(1);}if(src.some(x=>/^(SHARED|MODULE|OBJECT|IMPORTED|ALIAS|EXCLUDE_FROM_ALL|WIN32|MACOSX_BUNDLE)$/.test(x)))throw Error('Hedef türü desteklenmiyor.');targets.set(target,{kind,sources:src.map(x=>path(dir,x)),includes:[],defs:[],deps:[]});if(kind==='exe')executables.push(target);break;}
 case 'target_sources':if(rest[0]!=='PRIVATE')throw Error('target_sources PRIVATE gerekli');t().sources.push(...rest.slice(1).map(x=>path(dir,x)));break;
 case 'target_include_directories':case 'target_compile_definitions':case 'target_link_libraries':{const obj=t();let visibility='PUBLIC';for(const value of rest){if(['PRIVATE','PUBLIC','INTERFACE'].includes(value)){visibility=value;continue;}const key=cmd.name==='target_include_directories'?'includes':cmd.name==='target_compile_definitions'?'defs':'deps';if(key==='defs'&&!/^[A-Za-z_]\w*(?:=[A-Za-z0-9_+.-]+)?$/.test(value))throw Error('Makro değeri desteklenmiyor: '+value);obj[key].push({value:key==='includes'?path(dir,value):value,visibility});}break;}
 case 'pico_add_extra_outputs':case 'pico_enable_stdio_usb':case 'pico_enable_stdio_uart':{t();if(cmd.name==='pico_add_extra_outputs'&&rest.length)throw Error('pico_add_extra_outputs tek hedef alır');if(cmd.name!=='pico_add_extra_outputs'&&(!['0','1'].includes(rest[0])||rest.length!==1))throw Error('stdio 0/1 gerekli');if(cmd.name!=='pico_add_extra_outputs'){const obj=t();obj.stdio||={};obj.stdio[cmd.name==='pico_enable_stdio_usb'?'usb':'uart']=Number(rest[0]);}break;}
 default:throw Error('Desteklenmeyen CMake komutu: '+cmd.name);
 }}catch(e){throw Error(cmd.file+':'+cmd.line+': '+e.message);}}}
 read('CMakeLists.txt');if(executables.length!==1)throw Error('CMake: tek çalıştırılabilir hedef gerekli.');
 const result=new Map(),stack=new Set(),used=new Set();
 function usage(name,consumer=false){if(sdk.has(name))return{includes:[],defs:[]};if(!targets.has(name))throw Error('CMake: kütüphane bulunamadı veya desteklenmiyor: '+name);if(stack.has(name))throw Error('CMake: döngüsel hedef bağımlılığı');stack.add(name);const t=targets.get(name),out={includes:t.includes.filter(v=>consumer?v.visibility!=='PRIVATE':v.visibility!=='INTERFACE').map(v=>v.value),defs:t.defs.filter(v=>consumer?v.visibility!=='PRIVATE':v.visibility!=='INTERFACE').map(v=>v.value)};for(const d of t.deps.filter(d=>!consumer||d.visibility!=='PRIVATE')){const u=usage(d.value,true);out.includes.push(...u.includes);out.defs.push(...u.defs);}stack.delete(name);return out;}
 function visit(name){if(sdk.has(name)||used.has(name))return;used.add(name);const t=targets.get(name);if(!t)throw Error('CMake: tanımsız kütüphane '+name);const flags=usage(name);for(const f of t.sources){if(!all.has(f))throw Error('CMake: kaynak bulunamadı: '+f);if(f.endsWith('.h'))continue;if(!f.endsWith('.c'))throw Error('CMake: yalnız C kaynakları desteklenir: '+f);if(result.has(f))throw Error('CMake: kaynak birden çok hedefte derleniyor: '+f);result.set(f,{name:f,...flags});}for(const d of t.deps)visit(d.value);}
 visit(executables[0]);if(!result.has('main.c'))throw Error('CMake: hedef main.c dosyasını içermeli.');return{target:executables[0],units:[...result.values()],libraries:[...used].filter(n=>n!==executables[0]),stdio:{usb:0,uart:1,...targets.get(executables[0]).stdio},mode:'bounded-browser-cmake'};
}

export function picoCMakePlan(files,options={}){if(!files.some(f=>f.name==='CMakeLists.txt'))return null;const result=evaluateCMake(files,commands,options),plan=declarativePlan(result.files);return {...plan,generated:result.generated};}
